import { PoolClient } from 'pg';
import { pool } from './db';

interface CartItem {
  productId: string;
  quantity: number;
  price: number;
}

export async function processOrder(
  customerId: string,
  godownId: string,
  items: CartItem[]
): Promise<{ orderId: string }> {
  const client: PoolClient = await pool.connect();

  try {
    await client.query('BEGIN');

    // 1. Create order parent
    const orderRes = await client.query(
      `INSERT INTO orders (customer_id, status, created_at)
       VALUES ($1, 'confirmed', NOW())
       RETURNING id`,
      [customerId]
    );
    const orderId = orderRes.rows[0].id;

    // 2. Lock and reserve stock for each item in sorted order to avoid deadlocks
    const sortedItems = [...items].sort((a, b) => a.productId.localeCompare(b.productId));

    for (const item of sortedItems) {
      const stockRes = await client.query(
        `UPDATE warehouse_stock
         SET available_quantity = available_quantity - $1
         WHERE product_id = $2 AND godown_id = $3 AND available_quantity >= $1
         RETURNING available_quantity`,
        [item.quantity, item.productId, godownId]
      );

      if (stockRes.rowCount === 0) {
        throw new Error(`Insufficient stock for product ID: ${item.productId}`);
      }

      await client.query(
        `INSERT INTO order_items (order_id, product_id, quantity, unit_price)
         VALUES ($1, $2, $3, $4)`,
        [orderId, item.productId, item.quantity, item.price]
      );
    }

    await client.query('COMMIT');
    return { orderId };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
